export const BODY: string = "\n<p>إضافة علامة مائية تستغرق بضع دقائق فقط، وهي تحمي عملك أينما ذهبت الصورة. لا تحتاج برنامج تصميم ولا حسابًا، وكل العمل يعمل في متصفحك.</p>\n<p>في هذا البرنامج التعليمي نمر بالعملية كاملة خطوة بخطوة. سنرى العلامات المائية النصية وعلامات الشعار والموضع والشفافية والحجم والنمط المكرر الذي يحمي بروفات العملاء.</p>\n<p>في النهاية ستعرف كيف تضع علامة على صورة واحدة ودفعة من البروفات والأخطاء التي تجعل العلامة المائية عديمة الفائدة. واحتفظ بالأصل دون علامة حتى تراجع النتيجة.</p>\n<h2 id=\"before-you-start\">قبل أن تبدأ: ما تحتاجه</h2>\n<p>تحتاج ملف الصورة، وإذا أردت علامة شعار، تحتاج أيضًا ملف الشعار. يعمل شعار PNG شفاف أفضل، لأن مناطقه الفارغة تترك الصورة ظاهرة تحته.</p>\n<p>قرر ما يجب أن تقوله العلامة المائية قبل فتح الأداة. اسم أو موقع إلكتروني أو عبارة قصيرة تكفي، والنص القصير أسهل قراءة في الأحجام الصغيرة. وفكر أيضًا في هدفك: بروفة تحتاج علامة قوية يصعب إزالتها، بينما صورة منتهية للتواصل الاجتماعي تحتاج فقط علامة خفيفة في زاوية.</p>\n<p>افتح <a href=\"/ar/idafa-alama-maiyya/\">أداة العلامة المائية</a> في متصفحك. كل شيء يعمل محليًا، فصورك وشعارك لا تُرفع أبدًا إلى خادم.</p>\n<h2 id=\"step-by-step\">كيف تضيف علامة مائية في ست خطوات</h2>\n<p>العملية نفسها لعلامة مائية نصية أو علامة شعار. ارفع الصورة واضبط العلامة وضعها وراجع المعاينة ونزّل النتيجة.</p>\n<p>خذ وقتك مع الموضع والشفافية. هذان الضبطان يقرران هل العلامة المائية تحمي الصورة أم تزيّنها فقط. وافتح الملف المنزّل مرة قبل مشاركته، وتأكد من أن العلامة المائية تُقرأ بوضوح وأن الصورة تحتها ما زالت تبدو جيدة.</p>\n<ol>\n<li>ارفع صورتك بسحبها إلى منطقة الرفع أو اختيارها من جهازك أو لصقها بـCtrl+V.</li>\n<li>اكتب نص علامتك المائية، أو ارفع شعار PNG الشفاف بخيار الشعار.</li>\n<li>اختر موضعًا بإعدادات التثبيت المسبقة، أو اسحب العلامة المائية إلى مكان مخصص دقيق.</li>\n<li>اضبط الشفافية والحجم وزاوية التدوير، وفعّل النمط المتكرر المبلّط لبروفات العملاء.</li>\n<li>راجع النتيجة في الأجزاء الفاتحة والداكنة من الصورة لتأكيد أن العلامة تبقى مقروءة.</li>\n<li>اختر صيغة التصدير والجودة، ثم انقر تنزيل لحفظ الصورة ذات العلامة المائية.</li>\n</ol>\n<h2 id=\"choosing-text-or-logo\">كيف تختار بين علامة مائية نصية وعلامة شعار</h2>\n<p>العلامة المائية النصية هي الخيار الأسرع. اكتب اسمك أو موقعك الإلكتروني، وتظهر الأداة النص فوق الصورة في ثوانٍ دون ملفات إضافية.</p>\n<p>علامة الشعار تبدو أكثر احترافية، خصوصًا للمصورين والاستوديوهات. ارفع PNG شفافًا لعلامتك، فيظهر فوق الصورة كما صُمم. والنص أفضل عندما يكون الهدف إشعارًا واضحًا بحقوق النشر: اسم وسنة لا يتركان شكًا في الملكية، بينما شعار وحده قد لا يتعرف عليه غريب.</p>\n<p>يمكنك استخدام الاثنين معًا. شعار صغير في زاوية مع موقعك الإلكتروني مكتوبًا تحته يعطي علامة تجارية وإسنادًا في علامة واحدة.</p>\n<h2 id=\"typing-watermark-text\">كيف تكتب نص العلامة المائية</h2>\n<p>أبقِ النص قصيرًا. اسم أو اسم استوديو أو عنوان موقع يكفي، والنص القصير يبقى مقروءًا حتى بحجم صغير.</p>\n<p>تجنب الجمل الطويلة في علامة مائية. إشعار حقوق نشر كامل صعب القراءة فوق صورة مزدحمة، ويغطي من الصورة أكثر مما يلزم. واستخدم اسمك الحقيقي أو اسم عملك، لا لقبًا لا يعرفه أحد: العلامة المائية يجب أن تعرّف بك، فيجب أن تقول من أنت.</p>\n<p>إذا تركت حقل النص فارغًا، فالأداة ليس لديها ما تعرضه كعلامة نصية. اكتب النص أولًا ثم اضبط الحجم والموضع.</p>\n<h2 id=\"uploading-a-logo\">كيف ترفع شعارك كعلامة مائية</h2>\n<p>جهّز شعارك كـPNG شفاف قبل أن تبدأ. الشفافية تترك الصورة ظاهرة عبر المناطق الفارغة، فيظهر الشعار نفسه فقط فوق الصورة.</p>\n<p>شعار JPG له خلفية بيضاء صلبة تظهر كمستطيل فوق صورتك. يبدو غير احترافي، ومن السهل اكتشافه كخطأ. وارفع الشعار بخيار الشعار في الأداة. ويمكنك استبداله لاحقًا دون إعادة تحميل الصفحة، ما يفيد عندما تريد تجربة علامة مختلفة.</p>\n<p>راجع الشعار بالحجم الذي ستستخدمه به. شعار مفصل يبدو جيدًا بالحجم الكامل قد يصبح لطخة بحجم علامة مائية صغير، فبسّطه إذا لزم الأمر.</p>\n<h2 id=\"choosing-placement\">كيف تختار أين تذهب العلامة المائية</h2>\n<p>إعدادات التثبيت المسبقة تضع العلامة في مكان معياري: زاوية أو حافة أو وسط. الزوايا أقل إزعاجًا، بينما الوسط أصعب إزالة.</p>\n<p>اسحب العلامة المائية إلى مكان مخصص دقيق عندما لا تناسب الإعدادات المسبقة. يمكنك وضع العلامة فوق منطقة ناعمة من الصورة، حيث تُقرأ دون تغطية الموضوع. وللعلامة التجارية، زاوية سفلية غالبًا هي الأفضل: تسم الصورة بوضوح دون تغطية الموضوع، والمشاهدون يتوقعون إيجاد شعار هناك.</p>\n<p>وللحماية، الوسط أو موضع قطري أفضل. علامة في المنتصف لا يمكن قصها دون تدمير الصورة نفسها.</p>\n<h2 id=\"setting-opacity\">كيف تضبط الشفافية</h2>\n<p>الشفافية تتحكم في قوة ظهور العلامة المائية. عند 100 بالمئة تكون صلبة وتغطي الصورة تحتها، بينما عند 10 بالمئة تكون شبحًا باهتًا يسهل تجاهله.</p>\n<p>لبروفات العملاء، استخدم 30 إلى 50 بالمئة. تُقرأ العلامة بوضوح، ما يثني عن سوء الاستخدام، لكن العميل ما زال يستطيع الحكم على الصورة تحتها. ولعلامة تجارية على صورة منتهية، 15 إلى 25 بالمئة غالبًا يكفي: الشعار يُرى دون تشتيت عن الصورة، ولا ينافس الموضوع على الانتباه.</p>\n<p>اختبر الشفافية في الأجزاء الفاتحة والداكنة من الصورة. علامة فاتحة فوق خلفية داكنة قد تختفي في سماء ساطعة، والعكس أيضًا.</p>\n<h2 id=\"setting-size\">كيف تضبط حجم العلامة المائية</h2>\n<p>يُحجّم نص العلامة المائية كنسبة مئوية من الصورة، لا كعدد بكسلات ثابت. نفس الضبط يبدو متسقًا في صورة مصغرة صغيرة وفي صورة كاميرا ضخمة.</p>\n<p>حجم يبدو جيدًا في صورة كبيرة قد يكون غير مرئي في صورة صغيرة إذا حُدد بالبكسلات. التحجيم بالنسبة المئوية يتجنب هذه المشكلة تمامًا. وراجع الحجم بالأبعاد الحقيقية التي ستشارك بها: علامة تبدو لطيفة بالحجم الكامل قد تهيمن على معاينة صغيرة، وعلامة محجّمة لمصغرة قد تختفي في صورة كاملة.</p>\n<p>عند وضع علامة على دفعة صور بأحجام مختلفة، التحجيم بالنسبة المئوية يبقي النتيجة متسقة عبرها كلها دون عمل إضافي منك.</p>\n<h2 id=\"setting-rotation\">كيف تضبط زاوية التدوير</h2>\n<p>زاوية طفيفة، غالبًا حوالي 30 إلى 45 درجة، تجعل العلامة المائية أصعب إزالة وأقل شبهًا بعنوان. علامة قطرية تعبر جزءًا أكبر من الصورة من علامة أفقية.</p>\n<p>للبروفات، علامة قطرية هي الخيار الأقوى. تمر عبر الوسط والحواف، فلا يمكن لأي قص إزالتها دون ترك أثر. وللعلامة التجارية، أبقِ الزاوية صفرًا: شعار مستقيم في زاوية يبدو احترافيًا، بينما شعار مائل يبدو كخطأ تسلل.</p>\n<p>اضبط الزاوية بخطوات صغيرة ولاحظ المعاينة. بضع درجات قد تصنع الفرق بين علامة تبدو مقصودة وأخرى تبدو عرضية.</p>\n<h2 id=\"tiled-repeat-mode\">كيف تستخدم النمط المتكرر المبلّط</h2>\n<p>علامة مائية واحدة في زاوية سهلة الإزالة، لأن أي شخص يستطيع قص زاوية أو الطلاء فوق علامة صغيرة. النمط المبلّط يحل هذه المشكلة.</p>\n<p>وضع التبليط يضع العلامة المائية مرارًا عبر الصورة كلها في شبكة، فلا يمكن لأي قص إزالتها كلها. إنه المعيار لبروفات العملاء. وعند تفعيل وضع التبليط، تُخفى إعدادات التثبيت المسبقة، لأن النمط يغطي الإطار كله بالتصميم: أنت تتحكم في التباعد والزاوية.</p>\n<p>استخدم شفافية أقل للعلامات المبلّطة من العلامات المفردة. نمط متكرر بشفافية عالية يطغى على الصورة، بينما تكرار خفيف يحميها دون إخفائها.</p>\n<h2 id=\"preview-and-compare\">كيف تراجع المعاينة قبل التنزيل</h2>\n<p>راجع المعاينة دائمًا قبل التنزيل. تُظهر المعاينة بالضبط كيف ستبدو العلامة المائية في الملف المصدّر، بما فيها حجمها وشفافيتها وموضعها.</p>\n<p>راجع العلامة في أكثر جزء مزدحم من الصورة. علامة مائية تُقرأ بوضوح على جدار ناعم قد تختفي في غابة أو حشد أو قماش منقوش. وراجعها أيضًا في المناطق الأشد سطوعًا والأشد ظلامًا: علامة بيضاء تختفي في سماء ساطعة، وعلامة داكنة تختفي في ظل، فاختبر الطرفين.</p>\n<p>إذا كانت العلامة غير مقروءة في مكان مهم، غيّر لونها أو أضف حدًا أو انقلها إلى منطقة أنعم. تصحيحها الآن أسرع من إعادة العمل كله.</p>\n<h2 id=\"choosing-export-format\">كيف تختار صيغة التصدير</h2>\n<p>اختر JPG للصور التي تنوي مشاركتها أو إرسالها للعملاء. يبقي الملفات صغيرة ويعمل في كل مكان، بما فيه النماذج القديمة وتطبيقات المراسلة.</p>\n<p>اختر PNG عندما تكون الصورة الأساسية رسمًا شفافًا أو شعارًا. يحتفظ PNG بالشفافية، فتبقى المناطق الشفافة شفافة في التصدير. واختر WebP عندما تريد ملفات صغيرة بجودة جيدة: يعمل جيدًا لصور الويب، مع أن بعض الأنظمة القديمة ما زالت ترفض الصيغة.</p>\n<p>تذكر أن منزلق الجودة يُخفى لـPNG، لأن PNG دون فقدان وليس له ضبط جودة لتغييره. هذا سلوك طبيعي، لا مشكلة في الأداة.</p>\n<h2 id=\"watermarking-on-mobile\">كيف تضع علامات مائية على الهاتف أو الجهاز اللوحي</h2>\n<p>تعمل الأداة على شاشات اللمس، فتستطيع وضع علامة على صورة على الهاتف نفسه الذي التقطها. ارفعها من معرضك واكتب النص واسحب العلامة إلى مكانها بإصبعك.</p>\n<p>الوضع بالإصبع أقل دقة من الفأرة، فاستخدم إعدادات التثبيت المسبقة لزوايا دقيقة: تضع العلامة بإتقان دون سحب شيء. وراجع المعاينة بالحجم الكامل قبل التنزيل: علامة تبدو جيدة على شاشة هاتف صغيرة قد تكون كبيرة جدًا أو باهتة جدًا عند رؤيتها على حاسوب.</p>\n<p>تُحفظ الملفات المنزّلة في مجلد التنزيلات المعتاد لديك. ومن هناك يمكنك مشاركتها مباشرة إلى عميل أو بريد أو منشور اجتماعي.</p>\n<h2 id=\"troubleshooting\">حل المشاكل الشائعة مع العلامات المائية</h2>\n<p>إذا كانت العلامة المائية غير مرئية، فالشفافية منخفضة جدًا غالبًا أو اللون يطابق الخلفية. ارفع الشفافية أو غيّر اللون وراجع المعاينة مجددًا.</p>\n<p>وإذا غطت العلامة المائية الموضوع، انقلها إلى منطقة أنعم أو صغّر حجمها: علامة تخفي الوجه أو المنتج تُحبط غرض الصورة. وإذا فقدت إعدادات التثبيت المسبقة، راجع إن كان وضع التبليط مفعّلًا: تُخفى الإعدادات في وضع التبليط لأن النمط يغطي الإطار كله، وتعود عند إيقافه.</p>\n<p>وإذا أظهر الشعار مربعًا أبيض، فملف الشعار JPG لا PNG شفاف. استبدله بـPNG شفاف وسيختفي المستطيل الأبيض.</p>\n<h2 id=\"quick-tips\">نصائح سريعة لعلامات مائية أفضل</h2>\n<p>ضع علامة على نسخة، لا على الأصل أبدًا. بمجرد أن تندمج علامة في تصدير، لا يمكن إزالتها من ذلك الملف، فالأصل هو نسختك النظيفة الوحيدة.</p>\n<p>أبقِ النص قصيرًا والشعار بسيطًا. علامة سهلة القراءة بنظرة تحمي أفضل من علامة مفصلة تصبح لطخة. واختبر العلامة المائية على صورة مزدحمة قبل تطبيقها على دفعة كاملة: علامة تعمل على خلفية ناعمة قد تفشل في مشهد معقد.</p>\n<p>احفظ ضبطك بتدوينه: الشفافية والحجم والزاوية والموضع. ملاحظة قصيرة تتيح لك إعادة إنتاج نفس العلامة في كل صورة تنشرها.</p>\n<h2 id=\"watermarking-a-batch\">كيف تضع علامة على دفعة صور</h2>\n<p>حفل زفاف أو حدث قد ينتج مئات الصور التي تحتاج نفس العلامة. ضع علامة عليها واحدة في كل مرة، محافظًا على الضبط نفسه في المجموعة كلها.</p>\n<p>اكتب ضبطك قبل أن تبدأ: النص أو الشعار والشفافية والحجم والزاوية والموضع. ملاحظة قصيرة تبقي كل صورة في الدفعة متسقة. واعمل على الدفعة بالترتيب وراجع كل صورة عاشرة: مراجعة سريعة تكتشف ضبطًا انحرف قبل أن يؤثر في عشرات الملفات.</p>\n<p>احفظ الدفعة ذات العلامة المائية في مجلد منفصل عن الأصول. اسم مجلد واضح، مثل بروفات-بعلامة، يمنعك من خلط الملفات الموسومة والنظيفة.</p>\n<p>لقواعد الموضع والعلامة التجارية، اقرأ <a href=\"/ar/blog/afdal-mumarasat-lil-alama-al-maiyya/\">أفضل ممارسات العلامات المائية: الموضع والشفافية والعلامة التجارية</a>. وللدليل الكامل، راجع <a href=\"/ar/blog/dalil-al-alama-al-maiyya-lil-suwar/\">العلامة المائية للصور: الدليل الكامل</a>، ولإضافة نص بدل وضع علامة ملكية جرّب <a href=\"/ar/idafa-nass-ila-as-sura/\">أداة إضافة نص إلى صورة</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كيف أضيف علامة مائية إلى صورة على هاتفي؟","answer":"افتح أداة العلامة المائية في متصفح هاتفك وارفع الصورة من معرضك واكتب نصك أو ارفع شعار PNG شفاف. واستخدم إعدادات التثبيت المسبقة لموضع دقيق، ثم راجع المعاينة ونزّل النتيجة."},{"question":"ما أفضل موضع لعلامة مائية على صورة؟","answer":"زاوية سفلية هي الأفضل للعلامة التجارية، إذ تسم الصورة دون تغطية الموضوع. والوسط أو موضع قطري هو الأفضل للحماية، إذ لا يمكن قصه. اختر بحسب ما إذا كنت تريد علامة تجارية أم حماية."},{"question":"هل يمكنني وضع علامة على عدة صور دفعة واحدة؟","answer":"الأداة تتعامل مع صورة واحدة في كل مرة، فضع علامة على كل صورة منفصلة وحافظ على الضبط متسقًا. ودوّن شفافيتك وحجمك وزاويتك وموضعك ليحمل كل صورة في المجموعة نفس العلامة."},{"question":"لماذا علامتي المائية غير مرئية في بعض أجزاء الصورة؟","answer":"لون العلامة يطابق الخلفية في تلك المناطق غالبًا. النص الأبيض يختفي في سماء ساطعة والنص الداكن يختفي في الظلال. غيّر اللون أو أضف حدًا أو انقل العلامة إلى منطقة أنعم."},{"question":"كيف أصنع علامة مائية لا يمكن قصها؟","answer":"استخدم النمط المتكرر المبلّط، الذي يضع العلامة المائية عبر الصورة كلها في شبكة. لا يمكن لأي قص إزالتها كلها. واجمع التبليط مع زاوية قطرية وشفافية معتدلة لأقوى حماية."},{"question":"هل إضافة علامة مائية تغيّر حجم ملف الصورة؟","answer":"قليلًا فقط. العلامة المائية تضيف كمية صغيرة من البيانات، لكن حجم الملف يعتمد أساسًا على صيغة التصدير وضبط الجودة. تصدير JPG بضبط جودة مرتفع يبقى الملف صغيرًا نسبيًا."}];
